{"api_file": {"path": "src/api/locationHostApi.ts", "content": "const BASE_URL = import.meta.env.VITE_API_URL ?? "https://smartloansbackend.azurewebsites.net";

export interface LocationHost {
  locationHostId: number;
  companyId: number;
  channelId: number;
  contactPhone: string;
  marketingLeadAttributionId: number | null;
  origin: string;
  businessName: string;
  businessType: string | null;
  contactName: string | null;
  contactRole: string | null;
  zoneText: string;
  addressText: string | null;
  zoneName: string | null;
  zoneLat: number | null;
  zoneLng: number | null;
  openingHours: string | null;
  opensWeekends: boolean | null;
  spaceType: string | null;
  dailyVisitors: string | null;
  hasParking: boolean | null;
  contactOptIn: boolean;
  optInAt: string | null;
  status: string;
  staffNotes: string | null;
  created_At: string;
  updated_at: string | null;
}

export interface LocationHostListResponse {
  locationHosts: LocationHost[];
}

// GET ALL - POST /all_locationHosts
export async function getAllLocationHosts(
  companyId: number,
  userId: number,
  filters?: { status?: string; zoneName?: string; startDate?: string; endDate?: string }
): Promise<LocationHost[]> {
  const payload = {
    locationHosts: [{
      companyId,
      userId,
      ...(filters?.status && { status: filters.status }),
      ...(filters?.zoneName && { zoneName: filters.zoneName }),
      ...(filters?.startDate && { startDate: filters.startDate }),
      ...(filters?.endDate && { endDate: filters.endDate }),
    }],
  };
  const res = await fetch(BASE_URL + "/all_locationHosts", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: { result: LocationHostListResponse[] } = await res.json();
  return data.result?.[0]?.locationHosts ?? [];
}

// UPDATE STATUS - POST /locationHosts/status
export async function updateLocationHostStatus(
  locationHostId: number,
  companyId: number,
  userId: number,
  status: string,
  staffNotes: string | null
): Promise<{ locationHostId: number; status: string }> {
  const payload = {
    locationHosts: [{
      companyId,
      userId,
      locationHostId,
      status,
      staffNotes,
    }],
  };
  const res = await fetch(BASE_URL + "/locationHosts/status", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: { result: { locationHostId: number; status: string }[] } = await res.json();
  return data.result?.[0] || { locationHostId, status: "error" };
}
