import { useIonViewWillEnter } from '@ionic/react';
import { useUser } from '../../../contexts/UserContext';
import { useToast } from '../../../hooks/useToast';
import { onDataChanged, notifyDataChanged } from '../../../utils/refreshBus';
import { getAllLocationHosts, updateLocationHostStatus, LocationHost } from '../../../api/locationHostApi';
import { mxDate } from '../../../utils/format';

interface LocationHostFilters {
  status?: string;
  zoneName?: string;
  startDate?: string;
  endDate?: string;
}

export const useLocationHost = () => {
  const { companyId, userId } = useUser();
  const { showToast, toastProps } = useToast();
  const [items, setItems] = useState<LocationHost[]>([]);
  const [loading, setLoading] = useState(false);
  const [isSavingStatus, setIsSavingStatus] = useState(false);
  const [filters, setFilters] = useState<LocationHostFilters>({
    startDate: mxDate(new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString()), // Default last 90 days
    endDate: mxDate(new Date().toISOString()),
  });
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(true);

  const [newStatus, setNewStatus] = useState('');
  const [newStaffNotes, setNewStaffNotes] = useState('');

  const ITEMS_PER_PAGE = 20;
  const allItemsRef = useRef<LocationHost[]>([]);

  const load = useCallback(async (reset = false) => {
    if (reset) {
      setLoading(true);
      setPage(0);
      setHasMore(true);
      allItemsRef.current = [];
    }
    if (!hasMore && !reset) return;

    try {
      const response = await getAllLocationHosts(companyId, userId, filters);
      const sortedResponse = response.sort((a, b) => new Date(b.created_At).getTime() - new Date(a.created_At).getTime());

      if (reset) {
        allItemsRef.current = sortedResponse;
      } else {
        allItemsRef.current = [...allItemsRef.current, ...sortedResponse];
      }
      setItems(allItemsRef.current.slice(0, (page + 1) * ITEMS_PER_PAGE));
      setHasMore(allItemsRef.current.length > (page + 1) * ITEMS_PER_PAGE);
    } catch (err) {
      showToast((err as Error).message ?? 'Error desconocido al cargar socios de ubicación', 'danger');
      setHasMore(false);
    } finally {
      setLoading(false);
    }
  }, [companyId, userId, filters, page, hasMore, showToast]);

  const loadMoreItems = useCallback(() => {
    if (!loading && hasMore) {
      const nextPage = page + 1;
      setPage(nextPage);
      setItems(allItemsRef.current.slice(0, (nextPage + 1) * ITEMS_PER_PAGE));
      setHasMore(allItemsRef.current.length > (nextPage + 1) * ITEMS_PER_PAGE);
    }
  }, [loading, hasMore, page]);

  const handleUpdateStatus = useCallback(async (locationHostId: number, status: string, staffNotes: string | null) => {
    setIsSavingStatus(true);
    try {
      const updated = await updateLocationHostStatus(locationHostId, companyId, userId, status, staffNotes);
      setItems(prevItems =>
        prevItems.map(item =>
          item.locationHostId === updated.locationHostId ? { ...item, status: updated.status, staffNotes: staffNotes } : item
        )
      );
      showToast('Estado actualizado correctamente', 'success');
      notifyDataChanged('locationHost-status-updated');
    } catch (err) {
      showToast((err as Error).message ?? 'Error al actualizar el estado', 'danger');
    } finally {
      setIsSavingStatus(false);
    }
  }, [companyId, userId, showToast]);

  useEffect(() => {
    load(true); // Initial load or reload when filters change
  }, [load, filters]);

  useIonViewWillEnter(() => {
    load(true); // Reload on view re-entry to ensure fresh data
  });

  useEffect(() => onDataChanged(() => load(true)), [load]);

  return {
    items,
    loading,
    isSavingStatus,
    toastProps,
    filters,
    setFilters,
    hasMore,
    loadMoreItems,
    newStatus,
    setNewStatus,
    newStaffNotes,
    setNewStaffNotes,
    handleUpdateStatus,
  };
};

export type LocationHostVM = ReturnType<typeof useLocationHost>;
